import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { server } from '../test/mocks/server'
import { errorHandlers } from '../test/mocks/handlers'
import { fetchAssignments, rewriteCanvasNextLink } from './canvas'
import { useSettingsStore } from '../store/settingsStore'

describe('fetchAssignments', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2025-02-01T12:00:00Z'))

    // Set up mock settings before each test
    useSettingsStore.setState({
      canvasInstances: [{
        id: 'test-instance',
        name: 'Test School',
        token: 'test-token',
        url: 'test.instructure.com',
      }],
      timeframeDays: 30,
    })
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('fetches and transforms per-course assignments', async () => {
    const { assignments, failures } = await fetchAssignments()

    expect(assignments).toHaveLength(2)
    expect(failures).toEqual([])
    expect(assignments[0]).toMatchObject({
      id: 'test-instance:1001',
      instance_id: 'test-instance',
      name: 'Homework 1',
      course_name: 'Intro to Computer Science',
    })
    expect(assignments[1]).toMatchObject({
      id: 'test-instance:1002',
      name: 'Quiz 2',
      course_name: 'Calculus I',
    })
  })

  it('handles all_day_date by converting to ISO format', async () => {
    const { assignments } = await fetchAssignments()

    // all_day_date should be converted to ISO format with T23:59:59Z
    expect(assignments[0].due_at).toBe('2025-02-10T23:59:59Z')
  })

  it('uses start_at/end_at when all_day_date is null', async () => {
    const { assignments } = await fetchAssignments()

    // Should use end_at when all_day_date is null
    expect(assignments[1].due_at).toBe('2025-02-15T11:00:00Z')
  })

  it('throws error on 401 unauthorized', async () => {
    server.use(errorHandlers.unauthorized)

    await expect(fetchAssignments()).rejects.toThrow('Test School: Invalid Canvas token')
  })

  it('throws error on server errors', async () => {
    server.use(errorHandlers.serverError)

    await expect(fetchAssignments()).rejects.toThrow('Test School: Canvas API error: 500')
  })

  it('rejects an unsafe pagination link before following it', async () => {
    server.use(errorHandlers.invalidPaginationLink)

    await expect(fetchAssignments()).rejects.toThrow(
      'Test School: Canvas returned an invalid pagination link'
    )
  })

  it('throws when every course returns malformed assignment data', async () => {
    server.use(errorHandlers.invalidJson)

    await expect(fetchAssignments()).rejects.toThrow(
      'Test School: Canvas returned an invalid JSON response'
    )
  })

  it('reports a failed course while keeping successful assignments', async () => {
    server.use(errorHandlers.oneInvalidCourse)

    await expect(fetchAssignments()).resolves.toEqual({
      assignments: [
        expect.objectContaining({
          id: 'test-instance:1002',
          course_name: 'Calculus I',
        }),
      ],
      failures: [
        expect.objectContaining({
          instanceId: 'test-instance',
          courseId: '123456',
          courseName: 'Intro to Computer Science',
        }),
      ],
    })
  })
})

describe('rewriteCanvasNextLink', () => {
  it('rewrites absolute and root-relative Canvas API links through the proxy', () => {
    expect(rewriteCanvasNextLink(
      'https://school.instructure.com/api/v1/courses?page=2&per_page=100'
    )).toBe('/api/canvas/courses?page=2&per_page=100')
    expect(rewriteCanvasNextLink('/api/v1/courses?page=3')).toBe(
      '/api/canvas/courses?page=3'
    )
  })

  it('strips an unexpected upstream host instead of sending it the Canvas token', () => {
    expect(rewriteCanvasNextLink(
      'https://attacker.example/api/v1/courses?page=2'
    )).toBe('/api/canvas/courses?page=2')
  })

  it.each([
    'https://attacker.example/collect?page=2',
    'javascript:alert(1)',
    '/not-the-canvas-api?page=2',
  ])('rejects pagination links outside the Canvas API: %s', (link) => {
    expect(() => rewriteCanvasNextLink(link)).toThrow(
      'Canvas returned an invalid pagination link'
    )
  })
})

import { z } from 'zod'
import { toLocalDateString } from '../utils/dateUtils'
import { useSettingsStore, type CanvasInstance } from '../store/settingsStore'

const CourseSchema = z.object({
  id: z.number(),
  name: z.string(),
})

const AssignmentSchema = z.object({
  id: z.number(),
  name: z.string(),
  due_at: z.string().nullable(),
})

export interface CanvasAssignment {
  id: string
  instance_id: string
  name: string
  due_at: string | null
  course_id: string
  course_name: string
}

export interface CanvasSyncFailure {
  instanceId: string
  instanceName: string
  courseId?: string
  courseName?: string
  message: string
}

export interface CanvasSyncResult {
  assignments: CanvasAssignment[]
  failures: CanvasSyncFailure[]
}

interface InstanceFetchResult {
  assignments: CanvasAssignment[]
  failures: CanvasSyncFailure[]
}

/**
 * Parse the Link header to find the "next" page URL.
 */
function parseNextLink(linkHeader: string | null): string | null {
  if (!linkHeader) return null
  const match = linkHeader.match(/<([^>]+)>;\s*rel="next"/)
  return match?.[1] ?? null
}

/**
 * Convert Canvas pagination URLs back into a same-origin proxy request.
 * Never return an upstream URL because the caller attaches the Canvas token.
 */
export function rewriteCanvasNextLink(nextLink: string): string {
  let parsed: URL
  try {
    parsed = new URL(nextLink, 'https://canvas.invalid')
  } catch {
    throw new Error('Canvas returned an invalid pagination link')
  }

  if (
    (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') ||
    (parsed.pathname !== '/api/v1' && !parsed.pathname.startsWith('/api/v1/'))
  ) {
    throw new Error('Canvas returned an invalid pagination link')
  }

  const apiPath = parsed.pathname.slice('/api/v1'.length) || '/'
  return `/api/canvas${apiPath}${parsed.search}`
}

/**
 * Fetch all pages from a paginated Canvas API endpoint.
 */
async function fetchAllPages(url: string, headers: Record<string, string>): Promise<unknown[]> {
  const results: unknown[] = []
  let nextUrl: string | null = url

  while (nextUrl) {
    const res = await fetch(nextUrl, { headers })
    if (!res.ok) {
      if (res.status === 401) throw new Error('Invalid Canvas token')
      throw new Error(`Canvas API error: ${res.status}`)
    }

    let data: unknown
    try {
      data = await res.json()
    } catch {
      throw new Error('Canvas returned an invalid JSON response')
    }
    if (!Array.isArray(data)) break
    results.push(...data)

    const linkHeader = res.headers.get('Link')
    const nextLink = parseNextLink(linkHeader)
    if (nextLink) {
      nextUrl = rewriteCanvasNextLink(nextLink)
    } else {
      nextUrl = null
    }
  }

  return results
}

/**
 * Fetch assignments from a single Canvas instance
 */
async function fetchFromInstance(instance: CanvasInstance): Promise<InstanceFetchResult> {
  const headers: Record<string, string> = {
    'Authorization': `Bearer ${instance.token}`,
    'X-Canvas-Host': instance.url,
  }

  // Get date range: today to N days out based on user's timeframe setting
  const { timeframeDays } = useSettingsStore.getState()
  const today = new Date()
  const endDay = new Date(Date.now() + timeframeDays * 24 * 60 * 60 * 1000)
  const startDate = toLocalDateString(today)
  const endDate = toLocalDateString(endDay)

  // Fetch all active courses with pagination
  const rawCourses = await fetchAllPages('/api/canvas/courses?enrollment_state=active&per_page=100', headers)

  const courses = rawCourses
    .map((course) => {
      const parsed = CourseSchema.safeParse(course)
      return parsed.success ? parsed.data : null
    })
    .filter((c): c is z.infer<typeof CourseSchema> => c !== null)

  if (courses.length === 0) {
    return { assignments: [], failures: [] }
  }

  // Fetch assignments from each course in parallel
  // Uses per-course endpoint instead of calendar_events (which some Canvas instances restrict)
  const courseResults = await Promise.allSettled(
    courses.map(async (course) => {
      const url = `/api/canvas/courses/${course.id}/assignments?per_page=100&order_by=due_at`
      const rawAssignments = await fetchAllPages(url, headers)
      return { course, assignments: rawAssignments }
    })
  )

  const successfulCourseRequests = courseResults.filter(
    (result): result is PromiseFulfilledResult<{
      course: z.infer<typeof CourseSchema>
      assignments: unknown[]
    }> => result.status === 'fulfilled'
  )

  if (successfulCourseRequests.length === 0) {
    const firstFailure = courseResults.find(
      (result): result is PromiseRejectedResult => result.status === 'rejected'
    )
    if (firstFailure?.reason instanceof Error) throw firstFailure.reason
    throw new Error('Failed to fetch assignments from Canvas')
  }

  const allAssignments: CanvasAssignment[] = []
  const failures: CanvasSyncFailure[] = []

  courseResults.forEach((result, index) => {
    if (result.status === 'rejected') {
      const course = courses[index]
      failures.push({
        instanceId: instance.id,
        instanceName: instance.name,
        courseId: String(course.id),
        courseName: course.name,
        message: result.reason instanceof Error ? result.reason.message : 'Failed to fetch course assignments',
      })
    }
  })

  for (const result of successfulCourseRequests) {
    const { course, assignments } = result.value

    for (const raw of assignments) {
      const parsed = AssignmentSchema.safeParse(raw)
      if (!parsed.success) continue

      const assignment = parsed.data
      if (!assignment.due_at) continue

      // Filter to assignments within the configured timeframe
      const dueDateStr = toLocalDateString(new Date(assignment.due_at))
      if (dueDateStr < startDate || dueDateStr > endDate) continue

      allAssignments.push({
        id: `${instance.id}:${assignment.id}`,
        instance_id: instance.id,
        name: assignment.name,
        due_at: assignment.due_at,
        course_id: String(course.id),
        course_name: course.name,
      })
    }
  }

  return { assignments: allAssignments, failures }
}

/**
 * Fetch assignments from all configured Canvas instances
 */
export async function fetchAssignments(): Promise<CanvasSyncResult> {
  const { canvasInstances } = useSettingsStore.getState()

  const validInstances = canvasInstances.filter(i => i.url && i.token)

  if (validInstances.length === 0) {
    throw new Error('No Canvas instances configured. Please add your schools in Settings.')
  }

  // Fetch from all instances in parallel
  const results = await Promise.allSettled(
    validInstances.map(instance => fetchFromInstance(instance))
  )

  // Collect all assignments and errors
  const allAssignments: CanvasAssignment[] = []
  const failures: CanvasSyncFailure[] = []
  let successfulInstances = 0

  results.forEach((result, index) => {
    if (result.status === 'fulfilled') {
      successfulInstances++
      allAssignments.push(...result.value.assignments)
      failures.push(...result.value.failures)
    } else {
      const instance = validInstances[index]
      failures.push({
        instanceId: instance.id,
        instanceName: instance.name,
        message: result.reason instanceof Error ? result.reason.message : 'Failed to fetch Canvas instance',
      })
    }
  })

  // If all instances failed, throw an error
  if (successfulInstances === 0 && failures.length > 0) {
    throw new Error(failures.map(failure => `${failure.instanceName}: ${failure.message}`).join('; '))
  }

  // Log warnings for partial failures but still return results
  if (failures.length > 0) {
    console.warn('Some Canvas requests failed:', failures)
  }

  return { assignments: allAssignments, failures }
}

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { fetchAssignments } from '../lib/canvas'
import { useTaskStore } from './taskStore'

vi.mock('../lib/canvas', () => ({
  fetchAssignments: vi.fn(),
}))

describe('taskStore', () => {
  beforeEach(() => {
    // Reset store state before each test
    useTaskStore.setState({
      tasks: [],
      lastFetched: null,
      syncing: false,
      error: null,
      courseAliases: {},
      customOrder: [],
      customCourses: [],
    })
    vi.mocked(fetchAssignments).mockReset()
  })

  describe('addManualTask', () => {
    it('adds a new manual task with default course', () => {
      const { addManualTask } = useTaskStore.getState()

      addManualTask('Test task', null)

      const { tasks } = useTaskStore.getState()
      expect(tasks).toHaveLength(1)
      expect(tasks[0]).toMatchObject({
        title: 'Test task',
        dueDate: null,
        courseName: 'Personal',
        source: 'manual',
        completed: false,
      })
      expect(tasks[0].id).toMatch(/^manual-[0-9a-f-]{36}$/)
    })

    it('adds a task with due date and custom course', () => {
      const { addManualTask } = useTaskStore.getState()

      addManualTask('Task with date', '2025-02-15', 'Math')

      const { tasks } = useTaskStore.getState()
      expect(tasks[0]).toMatchObject({
        title: 'Task with date',
        dueDate: '2025-02-15',
        courseName: 'Math',
      })
    })

    it('keeps IDs unique when tasks are created in the same millisecond', () => {
      const now = vi.spyOn(Date, 'now').mockReturnValue(1_700_000_000_000)
      const { addManualTask } = useTaskStore.getState()

      addManualTask('First task', null)
      addManualTask('Second task', null)

      const ids = useTaskStore.getState().tasks.map(task => task.id)
      expect(new Set(ids).size).toBe(2)
      now.mockRestore()
    })
  })

  describe('toggleComplete', () => {
    it('toggles task completion status', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
        ],
      })

      const { toggleComplete } = useTaskStore.getState()

      toggleComplete('test-1')
      expect(useTaskStore.getState().tasks[0].completed).toBe(true)

      toggleComplete('test-1')
      expect(useTaskStore.getState().tasks[0].completed).toBe(false)
    })

    it('does not affect other tasks', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-2', title: 'Task 2', dueDate: null, courseName: 'Personal', source: 'manual', completed: true },
        ],
      })

      const { toggleComplete } = useTaskStore.getState()
      toggleComplete('test-1')

      const { tasks } = useTaskStore.getState()
      expect(tasks[0].completed).toBe(true)
      expect(tasks[1].completed).toBe(true)
    })
  })

  describe('syncCanvas', () => {
    it('preserves completion by assignment identity, not a shared title', async () => {
      useTaskStore.setState({
        tasks: [
          {
            id: 'canvas-school-a:101',
            title: 'Final Project',
            dueDate: '2025-02-10T12:00:00Z',
            courseName: 'Course A',
            source: 'canvas',
            completed: true,
          },
          {
            id: 'canvas-school-a:202',
            title: 'Final Project',
            dueDate: '2025-02-11T12:00:00Z',
            courseName: 'Course B',
            source: 'canvas',
            completed: false,
          },
        ],
      })
      vi.mocked(fetchAssignments).mockResolvedValue({
        assignments: [{
          id: 'school-a:101',
          instance_id: 'school-a',
          name: 'Renamed Final Project',
          due_at: '2025-02-12T12:00:00Z',
          course_id: '1',
          course_name: 'Course A',
        },
        {
          id: 'school-a:202',
          instance_id: 'school-a',
          name: 'Final Project',
          due_at: '2025-02-13T12:00:00Z',
          course_id: '2',
          course_name: 'Course B',
        }],
        failures: [],
      })

      await useTaskStore.getState().syncCanvas(true)

      expect(useTaskStore.getState().tasks).toEqual([
        expect.objectContaining({
          id: 'canvas-school-a:101',
          title: 'Renamed Final Project',
          completed: true,
        }),
        expect.objectContaining({
          id: 'canvas-school-a:202',
          title: 'Final Project',
          completed: false,
        }),
      ])
    })

    it('retains saved tasks only for Canvas courses that failed to refresh', async () => {
      useTaskStore.setState({
        tasks: [
          {
            id: 'canvas-school-a:101',
            title: 'Saved Course A task',
            dueDate: '2025-02-10T12:00:00Z',
            courseName: 'Course A',
            source: 'canvas',
            completed: true,
            canvasInstanceId: 'school-a',
            canvasCourseId: '1',
          },
          {
            id: 'canvas-school-a:202',
            title: 'Stale Course B task',
            dueDate: '2025-02-11T12:00:00Z',
            courseName: 'Course B',
            source: 'canvas',
            completed: false,
            canvasInstanceId: 'school-a',
            canvasCourseId: '2',
          },
          {
            id: 'manual-1',
            title: 'Personal task',
            dueDate: null,
            courseName: 'Personal',
            source: 'manual',
            completed: false,
          },
        ],
      })
      vi.mocked(fetchAssignments).mockResolvedValue({
        assignments: [{
          id: 'school-a:303',
          instance_id: 'school-a',
          name: 'Fresh Course B task',
          due_at: '2025-02-13T12:00:00Z',
          course_id: '2',
          course_name: 'Course B',
        }],
        failures: [{
          instanceId: 'school-a',
          instanceName: 'School A',
          courseId: '1',
          courseName: 'Course A',
          message: 'Canvas API error: 503',
        }],
      })

      await useTaskStore.getState().syncCanvas(true)

      expect(useTaskStore.getState().tasks).toEqual([
        expect.objectContaining({ id: 'canvas-school-a:303', title: 'Fresh Course B task' }),
        expect.objectContaining({ id: 'canvas-school-a:101', title: 'Saved Course A task', completed: true }),
        expect.objectContaining({ id: 'manual-1', title: 'Personal task' }),
      ])
      expect(useTaskStore.getState().error).toMatch(/previously saved assignments/)
    })
  })

  describe('reorderTasks', () => {
    it('reorders tasks based on drag position', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-2', title: 'Task 2', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-3', title: 'Task 3', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
        ],
        customOrder: [],
      })

      const { reorderTasks } = useTaskStore.getState()

      // Move task-1 to position of task-3
      reorderTasks('test-1', 'test-3')

      const { customOrder } = useTaskStore.getState()
      expect(customOrder).toEqual(['test-2', 'test-3', 'test-1'])
    })

    it('initializes customOrder from tasks if empty', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-2', title: 'Task 2', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
        ],
        customOrder: [],
      })

      const { reorderTasks } = useTaskStore.getState()
      reorderTasks('test-2', 'test-1')

      const { customOrder } = useTaskStore.getState()
      expect(customOrder).toContain('test-1')
      expect(customOrder).toContain('test-2')
    })
  })

  describe('addCustomCourse', () => {
    it('adds a new custom course', () => {
      const { addCustomCourse } = useTaskStore.getState()

      addCustomCourse('My Course')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toContain('My Course')
    })

    it('trims whitespace from course name', () => {
      const { addCustomCourse } = useTaskStore.getState()

      addCustomCourse('  Spaced Course  ')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toContain('Spaced Course')
    })

    it('does not add duplicate courses', () => {
      useTaskStore.setState({ customCourses: ['Existing'] })

      const { addCustomCourse } = useTaskStore.getState()
      addCustomCourse('Existing')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toEqual(['Existing'])
    })

    it('does not add empty course names', () => {
      const { addCustomCourse } = useTaskStore.getState()

      addCustomCourse('')
      addCustomCourse('   ')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toEqual([])
    })
  })

})

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import { fetchAssignments, type CanvasAssignment, type CanvasSyncFailure } from '../lib/canvas'
import type { Task } from '../schemas/task'

export type { Task }

export type DeleteStrategy =
  | { type: 'keep' }
  | { type: 'reassign'; target: string }
  | { type: 'delete' }

interface TaskStore {
  tasks: Task[]
  lastFetched: number | null
  syncing: boolean
  error: string | null
  courseAliases: Record<string, string>
  customOrder: string[]
  customCourses: string[]

  syncCanvas: (force?: boolean) => Promise<void>
  toggleComplete: (id: string) => void
  addManualTask: (title: string, dueDate: string | null, courseName?: string) => void
  deleteTask: (id: string) => void
  setCourseAlias: (original: string, alias: string) => void
  reorderTasks: (activeId: string, overId: string) => void
  addCustomCourse: (name: string) => void
  renameCourse: (courseName: string, newDisplayName: string) => void
  deleteCourse: (courseName: string, strategy: DeleteStrategy) => void
}

const STALE_THRESHOLD = 60 * 60 * 1000 // 1 hour

export const useTaskStore = create<TaskStore>()(
  persist(
    (set, get) => ({
      tasks: [],
      lastFetched: null,
      syncing: false,
      error: null,
      courseAliases: {},
      customOrder: [],
      customCourses: [],

      syncCanvas: async (force = false) => {
        const { lastFetched, syncing } = get()

        // Prevent concurrent syncs or syncing if data is fresh
        if (syncing) return
        if (!force && lastFetched && Date.now() - lastFetched < STALE_THRESHOLD) return

        set({ syncing: true, error: null })

        try {
          const syncResult = await fetchAssignments()
          const canvasTasks = syncResult.assignments.map(transformToTask)

          // Dedupe canvas tasks by ID
          const seenIds = new Set<string>()
          const uniqueCanvasTasks = canvasTasks.filter(t => {
            if (seenIds.has(t.id)) return false
            seenIds.add(t.id)
            return true
          })

          // Merge: keep manual tasks + completion state, update canvas tasks
          const { tasks: existingTasks } = get()
          const manualTasks = existingTasks.filter(t => t.source === 'manual')
          const staleTasksFromFailures = existingTasks.filter(
            task => task.source === 'canvas' && syncResult.failures.some(failure => taskMatchesFailure(task, failure))
          )

          // Canvas IDs include both the configured instance and assignment ID.
          // Titles are not identities: two courses commonly reuse names such as
          // "Final Project" or "Week 1 Discussion".
          const completedCanvasIds = new Set(
            existingTasks
              .filter(t => t.source === 'canvas' && t.completed)
              .map(t => t.id)
          )

          const mergedCanvasTasks = uniqueCanvasTasks.map(t => ({
            ...t,
            completed: completedCanvasIds.has(t.id)
          }))
          const refreshedIds = new Set(mergedCanvasTasks.map(task => task.id))
          const retainedStaleTasks = staleTasksFromFailures.filter(task => !refreshedIds.has(task.id))

          set({
            tasks: [...mergedCanvasTasks, ...retainedStaleTasks, ...manualTasks],
            lastFetched: Date.now(),
            syncing: false,
            error: syncResult.failures.length > 0
              ? 'Some Canvas courses could not be refreshed. Showing their previously saved assignments.'
              : null,
          })
        } catch (err) {
          set({
            error: err instanceof Error ? err.message : 'Sync failed',
            syncing: false
          })
        }
      },

      toggleComplete: (id) => set((state) => ({
        tasks: state.tasks.map(t =>
          t.id === id ? { ...t, completed: !t.completed } : t
        )
      })),

      addManualTask: (title, dueDate, courseName = 'Personal') => set((state) => ({
        tasks: [...state.tasks, {
          id: `manual-${crypto.randomUUID()}`,
          title,
          dueDate,
          courseName,
          source: 'manual' as const,
          completed: false,
        }]
      })),

      deleteTask: (id) => set((state) => ({
        tasks: state.tasks.filter(t => t.id !== id),
        customOrder: state.customOrder.filter(orderId => orderId !== id),
      })),

      setCourseAlias: (original, alias) => set((state) => ({
        courseAliases: {
          ...state.courseAliases,
          [original]: alias.trim() || original,
        }
      })),

      reorderTasks: (activeId, overId) => set((state) => {
        // If items aren't in customOrder yet, initialize from current task order
        let order = [...state.customOrder]
        const taskIds = state.tasks.map(t => t.id)

        // Add any missing task IDs to the order
        for (const id of taskIds) {
          if (!order.includes(id)) {
            order.push(id)
          }
        }
        // Remove any IDs no longer in tasks
        order = order.filter(id => taskIds.includes(id))

        const activeIdx = order.indexOf(activeId)
        const overIdx = order.indexOf(overId)

        if (activeIdx === -1 || overIdx === -1) return state

        // Move item from old position to new position
        order.splice(activeIdx, 1)
        order.splice(overIdx, 0, activeId)

        return { customOrder: order }
      }),

      addCustomCourse: (name) => set((state) => {
        const trimmed = name.trim()
        if (!trimmed || state.customCourses.includes(trimmed)) return state
        return { customCourses: [...state.customCourses, trimmed] }
      }),

      renameCourse: (courseName, newDisplayName) => set((state) => {
        const trimmed = newDisplayName.trim()
        if (!trimmed || trimmed === 'Personal') return state

        const hasCanvasTasks = state.tasks.some(
          t => t.source === 'canvas' && t.courseName === courseName
        )

        if (hasCanvasTasks) {
          // Canvas or mixed: use alias
          return {
            courseAliases: { ...state.courseAliases, [courseName]: trimmed }
          }
        }

        // Manual-only: rename directly on tasks and in customCourses
        return {
          tasks: state.tasks.map(t =>
            t.courseName === courseName ? { ...t, courseName: trimmed } : t
          ),
          customCourses: state.customCourses.map(c =>
            c === courseName ? trimmed : c
          ),
        }
      }),

      deleteCourse: (courseName, strategy) => set((state) => {
        let tasks = state.tasks
        let customOrder = state.customOrder

        switch (strategy.type) {
          case 'keep':
            tasks = tasks.map(t =>
              t.courseName === courseName ? { ...t, courseName: 'Personal' } : t
            )
            break
          case 'reassign':
            tasks = tasks.map(t =>
              t.courseName === courseName ? { ...t, courseName: strategy.target } : t
            )
            break
          case 'delete': {
            const deletedIds = new Set(
              tasks.filter(t => t.courseName === courseName).map(t => t.id)
            )
            tasks = tasks.filter(t => t.courseName !== courseName)
            customOrder = customOrder.filter(id => !deletedIds.has(id))
            break
          }
        }

        const { [courseName]: _, ...remainingAliases } = state.courseAliases

        return {
          tasks,
          customOrder,
          customCourses: state.customCourses.filter(c => c !== courseName),
          courseAliases: remainingAliases,
        }
      }),
    }),
    { name: 'school-checklist-tasks' }
  )
)

function transformToTask(assignment: CanvasAssignment): Task {
  return {
    id: `canvas-${assignment.id}`,
    title: assignment.name,
    dueDate: assignment.due_at,
    courseName: assignment.course_name,
    source: 'canvas',
    completed: false,
    canvasInstanceId: assignment.instance_id,
    canvasCourseId: assignment.course_id,
  }
}

function taskMatchesFailure(task: Task, failure: CanvasSyncFailure): boolean {
  const legacyInstanceId = task.id.startsWith('canvas-')
    ? task.id.slice('canvas-'.length).split(':')[0]
    : undefined
  const instanceId = task.canvasInstanceId ?? legacyInstanceId
  if (instanceId !== failure.instanceId) return false
  if (!failure.courseId) return true
  if (task.canvasCourseId) return task.canvasCourseId === failure.courseId
  return task.courseName === failure.courseName
}
